require_once __DIR__.'/../includes/auth.php';$pdo=openDatabase();$user=requireLogin($pdo);$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken($_POST);try{if(isset($_POST['role'])||isset($_POST['status']))throw new InvalidArgumentException('Role and status cannot be edited here.');saveProfile($pdo,(int)$user['user_id'],field('full_name'),field('email'));header('Location: profile.php',true,303);exit;}catch(Throwable $e){$error=$e;}}pageStart('Edit Profile');if($error)showError($error);echo '<form method="post">'.csrfField();formField('full_name','Name','text',$user['full_name']);formField('email','Email','email',$user['email']);echo '<button class="btn btn-primary">Save changes</button></form>';pageEnd();
